           ${record.custbody_po_ship_via}
          ${record.custbody_po_carrier_no}
          ${record.incoterm}
          ${record.custbody_po_custom_broker}
         
        
    
    <#if record.item?has_content>
    
        
        <#list record.item as item>
            <#if item_index==0>
                


                  Line/
Ligne  
                  ${item.quantity@label}/
Quantité
                    ${item.item@label}/
Produit numéro
