            </#if>


              ${item.line}  
              ${item.quantity}
                <#if item.vendorname?has_content>${item.vendorname}<#else>${item.custcol_nsps_item_number_only}</#if>
              ${item.description}<#if item.custcol_im_external_notes?has_content>
${item.custcol_im_external_notes}</#if>
                ${item.rate}
                ${item.amount}
            
        </#list>
        
    
    </#if>
    <#if record.expense?has_content>
    
        
        <#list record.expense as expense >
            <#if expense_index==0>
                


                    ${expense.category@label}
                    ${expense.account@label}
                    ${expense.amount@label}
                
                
            </#if>


                ${expense.category}
                ${expense.account}
                ${expense.amount}
            
        </#list>
        
    
    </#if>
    
    


            
